// pybuiltins.mjs
// Reimplementations of the Python builtins used by the source script,
// faithful to CPython's observable behavior.

/**
 * Error mirroring Python's ValueError.
 */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

/**
 * Reproduce Python's repr() for a string (used inside error messages).
 * Prefers single quotes; falls back to double quotes when the string
 * contains a single quote but no double quote.
 */
export function pyStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else {
      out += ch;
    }
  }
  return out + quote;
}

// Whitespace stripped by Python's int(): space plus \t\n\r\f\v.
const PY_INT_STRIP = /^[ \t\n\r\f\v]+|[ \t\n\r\f\v]+$/g;
// Valid body after stripping: optional sign, digits with single
// underscores allowed between digits (PEP 515).
const PY_INT_BODY = /^[+-]?\d+(?:_\d+)*$/;

/**
 * Reproduce Python's int(str) with base 10:
 *  - strips surrounding ASCII whitespace
 *  - accepts an optional leading '+' or '-'
 *  - accepts single underscores between digits
 *  - rejects empty strings, floats, junk, etc. with ValueError
 */
export function pyInt(value) {
  const stripped = String(value).replace(PY_INT_STRIP, '');
  if (!PY_INT_BODY.test(stripped)) {
    throw new PyValueError(
      `invalid literal for int() with base 10: ${pyStrRepr(String(value))}`
    );
  }
  const cleaned = stripped.replace(/_/g, '');
  return parseInt(cleaned, 10);
}

