// iterutils.mjs
// Reimplementation of the boltons.iterutils helpers used by the script.

/**
 * bucketize(src, key = Boolean)
 *
 * Groups the items of `src` into buckets according to the value returned
 * by `key(item)`. Mirrors boltons.iterutils.bucketize, which returns a
 * dict mapping each key to the list of items producing that key.
 *
 * A JavaScript Map is used because, like Python's dict, it preserves
 * insertion order: buckets appear in the order their key is first seen,
 * and items keep their original relative order within each bucket.
 */
export function bucketize(src, key = Boolean) {
  const buckets = new Map();
  for (const item of src) {
    const k = key(item);
    if (buckets.has(k)) {
      buckets.get(k).push(item);
    } else {
      buckets.set(k, [item]);
    }
  }
  return buckets;
}

