// pyformat.mjs
// Python repr()/str() formatting for the value kinds this program prints,
// so console.log output matches Python's print character by character.

import { pyStrRepr } from './pybuiltins.mjs';

/**
 * Reproduce Python's repr() for the supported value kinds:
 *  - Map            -> dict repr:  {key: value, ...}
 *  - Array          -> list repr:  [a, b, c]
 *  - boolean        -> True / False
 *  - number (int)   -> decimal digits
 *  - string         -> quoted repr
 *  - null/undefined -> None
 */
export function pyRepr(value) {
  if (value instanceof Map) {
    const parts = [];
    for (const [k, v] of value) {
      parts.push(`${pyRepr(k)}: ${pyRepr(v)}`);
    }
    return `{${parts.join(', ')}}`;
  }
  if (Array.isArray(value)) {
    return `[${value.map(pyRepr).join(', ')}]`;
  }
  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }
  if (typeof value === 'number') {
    return Object.is(value, -0) ? '0' : String(value);
  }
  if (typeof value === 'string') {
    return pyStrRepr(value);
  }
  if (value === null || value === undefined) {
    return 'None';
  }
  return String(value);
}

/**
 * Reproduce Python's str() / print() rendering for the supported kinds.
 * For containers, print() uses repr() of the container itself.
 */
export function pyStr(value) {
  return pyRepr(value);
}

