// argparse.mjs
// Minimal reimplementation of the Python argparse behavior exercised by
// the source script: one required option taking a single value, automatic
// -h/--help, GNU-style "--opt value" and "--opt=value" forms, unambiguous
// long-option abbreviations, negative-number handling, and argparse's
// exact usage/error formatting and exit codes (0 for help, 2 for errors).

// argparse's _negative_number_matcher: when the parser has no options that
// look like negative numbers, tokens matching this are treated as values.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function basename(p) {
  const parts = String(p).split(/[\\/]/);
  return parts[parts.length - 1] || String(p);
}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog !== undefined ? prog : basename(process.argv[1] || '');
    // options: [{ flags: [...], dest, metavar, required, help, isHelp }]
    this.options = [];
    this.addArgument(['-h', '--help'], {
      help: 'show this help message and exit',
      isHelp: true,
    });
  }

  addArgument(flags, { required = false, help = '', isHelp = false } = {}) {
    const flagList = Array.isArray(flags) ? flags : [flags];
    const longFlag = flagList.find((f) => f.startsWith('--')) || flagList[0];
    const dest = longFlag.replace(/^-+/, '').replace(/-/g, '_');
    // argparse: metavar defaults to the uppercased dest
    const metavar = isHelp ? null : dest.toUpperCase();
    this.options.push({ flags: flagList, dest, metavar, required, help, isHelp });
  }

  // ---- output helpers -------------------------------------------------

  formatUsage() {
    const parts = [];
    for (const opt of this.options) {
      const flag = opt.flags[0];
      if (opt.isHelp) {
        parts.push(`[${flag}]`);
      } else if (opt.required) {
        parts.push(`${flag} ${opt.metavar}`);
      } else {
        parts.push(`[${flag} ${opt.metavar}]`);
      }
    }
    return `usage: ${this.prog} ${parts.join(' ')}`;
  }

  formatHelp() {
    const lines = [this.formatUsage(), '', 'options:'];
    const entries = this.options.map((opt) => {
      const inv = opt.isHelp
        ? opt.flags.join(', ')
        : opt.flags.map((f) => `${f} ${opt.metavar}`).join(', ');
      return { inv, help: opt.help };
    });
    const maxInv = Math.max(...entries.map((e) => e.inv.length));
    for (const e of entries) {
      lines.push(`  ${e.inv.padEnd(maxInv)}  ${e.help}`);
    }
    return lines.join('\n');
  }

  printHelp() {
    process.stdout.write(this.formatHelp() + '\n');
  }

  error(message) {
    process.stderr.write(this.formatUsage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  // ---- parsing --------------------------------------------------------

  // Resolve a "--name" token (already split from any "=value") to an
  // option, honoring argparse's unambiguous-prefix abbreviation.
  matchLong(name) {
    const exact = this.options.find((o) => o.flags.includes(name));
    if (exact) return exact;
    const matches = this.options.filter((o) =>
      o.flags.some((f) => f.startsWith('--') && f.startsWith(name))
    );
    if (matches.length === 1) return matches[0];
    if (matches.length > 1) {
      this.error(`ambiguous option: ${name} could match ${matches
        .map((o) => o.flags.find((f) => f.startsWith(name)))
        .join(', ')}`);
    }
    return null;
  }

  parseArgs(argv) {
    const values = {};
    const seen = new Set();
    const extras = [];

    let i = 0;
    while (i < argv.length) {
      const token = argv[i];

      if (token.startsWith('--') && token.length > 2) {
        const eq = token.indexOf('=');
        const name = eq === -1 ? token : token.slice(0, eq);
        const opt = this.matchLong(name);
        if (!opt) {
          extras.push(token);
          i += 1;
          continue;
        }
        if (opt.isHelp) {
          this.printHelp();
          process.exit(0);
        }
        let value;
        if (eq !== -1) {
          value = token.slice(eq + 1);
        } else if (i + 1 < argv.length && !this.looksLikeOption(argv[i + 1])) {
          value = argv[i + 1];
          i += 1;
        } else {
          this.error(`argument ${opt.flags.join('/')}: expected one argument`);
        }
        values[opt.dest] = value;
        seen.add(opt.dest);
        i += 1;
        continue;
      }

      if (token.startsWith('-') && token.length > 1 && !NEGATIVE_NUMBER.test(token)) {
        if (token === '-h') {
          this.printHelp();
          process.exit(0);
        }
        extras.push(token);
        i += 1;
        continue;
      }

      // positional or negative-number-looking token: this script declares
      // no positionals, so it is an extra.
      extras.push(token);
      i += 1;
    }

    const missing = this.options.filter((o) => o.required && !seen.has(o.dest));
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing
          .map((o) => o.flags.join('/'))
          .join(', ')}`
      );
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return values;
  }

  // argparse treats a following token as this option's value unless it
  // looks like an option string (starts with '-' and is neither a bare
  // '-' nor a negative number).
  looksLikeOption(token) {
    if (!token.startsWith('-')) return false;
    if (token === '-') return false;
    if (NEGATIVE_NUMBER.test(token)) return false;
    return true;
  }
}

