// Node.js (ESM) port of test5.py:
//   bucketize comma-separated integers by parity and print the result
//   exactly as Python's print() would render the dict.

import { ArgumentParser } from './lib/argparse.mjs';
import { bucketize } from './lib/iterutils.mjs';
import { pyInt, PyValueError } from './lib/pybuiltins.mjs';
import { pyStr } from './lib/pyformat.mjs';

const parser = new ArgumentParser();
parser.addArgument('--a', {
  required: true,
  help: 'Comma-separated numbers',
});
const args = parser.parseArgs(process.argv.slice(2));

let numbers;
try {
  numbers = args.a.split(',').map((x) => pyInt(x));
} catch (err) {
  if (err instanceof PyValueError) {
    // Mirror CPython's unhandled-ValueError output and exit code 1.
    process.stderr.write('Traceback (most recent call last):\n');
    process.stderr.write('  File "test5.py", line 8, in <module>\n');
    process.stderr.write(`ValueError: ${err.message}\n`);
    process.exit(1);
  }
  throw err;
}

const result = bucketize(numbers, (x) => x % 2 === 0); // 按奇偶性分组
console.log(pyStr(result));

